#define pi 3.141592653589
vec3 Ray(float t, vec3 O, vec3 D) {
    return O + (t * D);
}
float random(float seed) {
    return cos(1000.*seed);
}
vec3 RRD(vec3 D) {
    D = vec3(D.x * random(iTime), D.y * random(iTime + 1.), D.z);
    return D;
}
float a(vec3 p1, vec3 p2, vec3 p3) {
    return 0.5 * length(cross(p2-p1,p3-p1));
}
vec3 normal(vec3 v1, vec3 v2, vec3 v3) {
    return normalize(cross((v2 - v1), (v3 - v1)));
}
vec2 dT(vec3 v1, vec3 v2, vec3 v3, vec3 O, vec3 D) {
    vec3 n = normal(v1, v2, v3); //plane's normal vector
    float t = dot(n, v1 - O)/dot(n, D);
    vec3 p = Ray(t, O, D); //intercection ray-plane
    float V=a(v1,v2,v3) - (a(p, v2,v3)+a(v1,p,v3)+a(v1,v2,p)); //area comparation
    if (abs(V) < 0.001 && t > 0.) {
        return vec2(1, t);
    }
    else {
        return vec2(0, 0);
    }
}


struct Triangle {
    vec3 a;
    vec3 b;
    vec3 c;
    float depth;
};

float calculateDepth(Triangle tri, vec3 cameraPos) { //made by ChatGPT
    return (distance(cameraPos, tri.a) + distance(cameraPos, tri.b) + distance(cameraPos, tri.c)) / 3.0;
}
void sortTriangles(inout Triangle tris[6]) { //made by ChatGPT
    for (int i = 0; i < 6; ++i) {
        for (int j = i + 1; j < 6; ++j) {
            if (tris[i].depth < tris[j].depth) {
                Triangle temp = tris[i];
                tris[i] = tris[j];
                tris[j] = temp;
            }
        }
    }
}
